function setViewMode(m){return setViewModes([m])}
function setViewModes(list){const picked=(Array.isArray(list)?list:[...(list&&list.selectedOptions||[])].map(o=>o.value)).filter(Boolean);let modes=picked.length?picked:['full'];if(modes.includes('full'))modes=['full'];if(modes.includes('neighborhood')&&!neighborhoodNodeId){if(selectedNodeId)neighborhoodNodeId=selectedNodeId;else{alert('Select or right-click a node first to use Selected Node Neighborhood view.');syncViewMenuSelects();return}}activeViewModes=modes;syncViewMenuSelects();hideMenus();renderGraph();updateStatusBar()}
