function renderNodeSearchList(){const list=document.getElementById('node-search-list');if(!list)return;const q=document.getElementById('node-search-input')?.value||'';const all=nodeSearchMatches(q),rows=all.slice(0,NODE_SEARCH_MAX_ROWS);list.innerHTML=rows.length?rows.map(n=>`<div class="ns-row" onclick="focusNodeById('${esc(n.id)}')"><span class="ns-row-label">${esc(n.label)}</span><span class="ns-row-type">${esc(n.type)}${n.metadata?.cmdbClass?' / '+esc(n.metadata.cmdbClass):''}</span></div>`).join('')+(all.length>rows.length?`<div class="ns-more muted">+${all.length-rows.length} more — refine your search</div>`:''):`<div class="ns-empty muted">No matching nodes.</div>`}
