function applyZoomLabelState(force){if(!networkInstance||!graphNodesDataSet||!graphEdgesDataSet)return;const scale=networkInstance.getScale(),hide=performanceMode==='fast'||(performanceMode==='auto'&&scale<0.55&&lastRenderedGraphStats.edges>250);if(!force&&zoomLabelState===hide)return;zoomLabelState=hide;const nodeUpdates=graphNodesDataSet.get().map(n=>({id:n.id,label:hide?(n.shortLabel||n.label):(n.fullLabel||n.label)}));const edgeUpdates=graphEdgesDataSet.get().map(e=>({id:e.id,label:hide?'':(e.fullLabel||e.label||'')}));graphNodesDataSet.update(nodeUpdates);graphEdgesDataSet.update(edgeUpdates)}

