function toggleInspectorPanel(){const panel=document.getElementById('inspector-panel');if(!panel)return;const collapsed=panel.classList.toggle('collapsed');const btn=document.getElementById('inspector-toggle');if(btn)btn.textContent=collapsed?'Show':'Hide'}
