function copyInspectorJson(kind,id){let obj=null;if(kind==='node')obj=getNode(id);else if(kind==='edge')obj=currentModelData.edges[Number(id)];else if(kind==='cluster')obj=getClusterSummary(id);if(!obj)return alert('Nothing to copy.');const txt=JSON.stringify(obj,null,2);if(navigator.clipboard&&navigator.clipboard.writeText)navigator.clipboard.writeText(txt).then(()=>alert('Copied JSON to clipboard.')).catch(()=>prompt('Copy JSON:',txt));else prompt('Copy JSON:',txt)}
