function showNodeInspector(nodeId){const n=getNode(nodeId);if(!n)return;selectedNodeId=nodeId;const ph=classPhase(n.type),phInfo=PHASE_UNLOCKS[ph]||{goal:'',unlocks:''};const edges=nodeRelationshipRows(nodeId);const inbound=edges.filter(e=>e.to===nodeId);const outbound=edges.filter(e=>e.from===nodeId);const counts=countBy(edges,e=>e.label||e.relationship);let meta='<div><label>Type (EA)</label><span>'+inspectorEsc(n.type)+'</span></div>'+(serviceNowClass(n.type)?'<div><label>ServiceNow class</label><span>'+inspectorEsc(serviceNowClass(n.type))+'</span></div>':'')+'<div><label>CSDM phase</label><span title="'+inspectorEsc(ph+' — '+phInfo.goal+' '+phInfo.unlocks)+'">'+phaseBadge(ph)+' <span class="inspector-phase-goal">'+inspectorEsc(phInfo.goal)+'</span>'+(inPhaseScope(n.type)?'':'<em class="inspector-oos">Outside your build scope ('+inspectorEsc(phaseScopeLabel())+'). It stays on the canvas'+(isNonOperational(n.type)?'':' and can still be failure-simulated')+', but the Interview, Guided Path and Topology builders will not create another one until you tick '+inspectorEsc(ph)+' with the Phase chips in the status bar.</em>')+'</span></div>'+'<div><label>ID</label><code>'+inspectorEsc(n.id)+'</code></div><div><label>Domain</label><span>'+inspectorEsc(n.domain||'Unknown')+'</span></div>';if(n.metadata&&n.metadata.cmdbClass)meta+='<div><label>CMDB Class</label><span>'+inspectorEsc(n.metadata.cmdbClass)+'</span></div>';window.CSDM_SCHEMA.getMetadataFields(n.type).filter(f=>f.key!=='description').forEach(f=>{const val=n.metadata&&n.metadata[f.key];meta+='<div><label>'+inspectorEsc(f.label)+'</label><span>'+inspectorEsc(val||'—')+'</span></div>'});renderInspector('<div class="inspector-title">Selected Node</div><h3>'+inspectorEsc(n.label)+'</h3><div class="inspector-meta">'+meta+'</div><p class="inspector-description">'+inspectorEsc(n.metadata&&n.metadata.description?n.metadata.description:'No description provided.')+'</p><div class="inspector-grid"><div><label>Inbound</label><strong>'+inbound.length+'</strong></div><div><label>Outbound</label><strong>'+outbound.length+'</strong></div><div><label>Total</label><strong>'+edges.length+'</strong></div></div><h4>Relationship Mix</h4>'+countsMarkup(counts)+'<h4>Outbound Connections</h4>'+connectionListMarkup(edges,nodeId,'out')+'<h4>Inbound Connections</h4>'+connectionListMarkup(edges,nodeId,'in')+'<h4>Possible Relationships From Here</h4>'+possibleRelationshipsMarkup(n.type)+'<div class="inspector-actions"><button type="button" onclick="openWhyNodeDialog(\''+inspectorEsc(n.id)+'\')">Why it matters</button><button type="button" onclick="openImpactDialog(\''+inspectorEsc(n.id)+'\')">Impact Analysis</button><button type="button" onclick="inspectorFocusNode(\''+inspectorEsc(n.id)+'\',1)">Focus 1-hop</button><button type="button" onclick="inspectorFocusNode(\''+inspectorEsc(n.id)+'\',2)">Focus 2-hop</button><button type="button" onclick="inspectorShowDomain(\''+inspectorEsc(n.domain||'Unknown')+'\')">Show Domain</button><button type="button" onclick="copyInspectorJson(\'node\',\''+inspectorEsc(n.id)+'\')">Copy Node JSON</button></div>')}
function showEdgeInspector(edgeId,visibleEdge){const original=currentModelData.edges[Number(edgeId)];const e=original||visibleEdge;if(!e)return;const from=getNode(e.from),to=getNode(e.to),label=e.label||e.relationship||'';const md=e.metadata||{};let meta='<div><label>From</label><button class="inspector-link" type="button" onclick="showNodeInspector(\''+inspectorEsc(e.from)+'\')">'+inspectorEsc(from?from.label:e.from)+'</button></div><div><label>To</label><button class="inspector-link" type="button" onclick="showNodeInspector(\''+inspectorEsc(e.to)+'\')">'+inspectorEsc(to?to.label:e.to)+'</button></div><div><label>Label (EA)</label><span>'+inspectorEsc(label)+'</span></div>'+(serviceNowRel(label)?'<div><label>ServiceNow relationship</label><span>'+inspectorEsc(serviceNowRel(label))+'</span></div>':'');if(md.sourceRelationship)meta+='<div><label>Source relationship</label><span>'+inspectorEsc(md.sourceRelationship)+'</span></div>';if(md.sourceBaseClass)meta+='<div><label>Source base class</label><span>'+inspectorEsc(md.sourceBaseClass)+'</span></div>';if(md.sourceDependentClass)meta+='<div><label>Source dependent class</label><span>'+inspectorEsc(md.sourceDependentClass)+'</span></div>';renderInspector('<div class="inspector-title">Selected Relationship</div><h3>'+inspectorEsc(label)+'</h3><div class="inspector-meta">'+meta+'</div><div class="inspector-actions"><button type="button" onclick="inspectorShowRelationship(\''+inspectorEsc(label)+'\')">Show Only This Relationship</button><button type="button" onclick="copyInspectorJson(\'edge\',\''+Number(edgeId)+'\')">Copy Edge JSON</button></div>')}
function getClusterSummary(domain){const members=currentModelData.nodes.filter(n=>(n.domain||'Unknown')===domain&&!['Business Capability','Business Application','Application Service','Business Service','Service Offering'].includes(n.type));const ids=new Set(members.map(n=>n.id));const touching=currentModelData.edges.filter(e=>ids.has(e.from)||ids.has(e.to));return{domain:domain,nodeCount:members.length,relationshipCount:touching.length,topClasses:countBy(members,n=>(n.metadata&&n.metadata.cmdbClass)||n.type),relationships:countBy(touching,e=>e.label||e.relationship)}}
function showClusterInspector(domain){const summary=getClusterSummary(domain);const expanded=expandedClusters&&expandedClusters.has(domain);const topClasses=Object.entries(summary.topClasses).sort((a,b)=>b[1]-a[1]).slice(0,10);const cls=topClasses.length?topClasses.map(([k,v])=>'<div class="inspector-count"><span>'+inspectorEsc(k)+'</span><strong>'+v+'</strong></div>').join(''):'<div class="inspector-muted">None</div>';renderInspector('<div class="inspector-title">Domain Cluster</div><h3>'+inspectorEsc(domain)+'</h3><div class="inspector-grid"><div><label>Nodes</label><strong>'+summary.nodeCount+'</strong></div><div><label>Touching relationships</label><strong>'+summary.relationshipCount+'</strong></div><div><label>Status</label><strong>'+(expanded?'Expanded':'Collapsed')+'</strong></div></div><h4>Top CMDB Classes</h4>'+cls+'<h4>Relationship Mix</h4>'+countsMarkup(summary.relationships)+'<div class="inspector-actions"><button type="button" onclick="toggleDomainCluster(\''+inspectorEsc(domain)+'\')">'+(expanded?'Collapse':'Expand')+' Cluster</button><button type="button" onclick="inspectorShowDomain(\''+inspectorEsc(domain)+'\')">Show Domain Summary</button><button type="button" onclick="copyInspectorJson(\'cluster\',\''+inspectorEsc(domain)+'\')">Copy Cluster Summary</button></div>')}

function buildStatsText(){const fg=getFilteredGraph();const rel=relFilterLabel(),cl=clusterMode==='off'?'Off':`Domain (${expandedClusters.size} expanded)`,perf=performanceMode==='auto'?(lastRenderedGraphStats.lightweight?'Auto/Fast':'Auto/Detail'):performanceMode;return `Model: ${currentModelData.seedModel||'Custom'}\nView Mode: ${viewModesLabel()}\nRelationship Filter: ${rel}\nCSDM Phase Scope: ${phaseScopeLabel()}\nCluster: ${cl}\nPerformance: ${perf}\nShowing: ${fg.nodes.length}/${currentModelData.nodes.length} nodes, ${fg.edges.length}/${currentModelData.edges.length} relationships\nUnsaved changes: ${hasUnsavedChanges()?'Yes':'No'}\nUndo available: ${undoStack.length}\nRedo available: ${redoStack.length}\nLearning Mode: ${learningMode?`On (${learningStats.correct}/${learningStats.attempts} correct this session)`:'Off'}`}function openAboutDialog(){document.getElementById('modal-title').textContent='About';document.getElementById('modal-body').innerHTML=`<div class="readonly"><p style="margin:0 0 8px"><strong>CSDM Deep-Linker Sandbox</strong></p><p class="muted" style="margin:0 0 8px">Version 3.7.0</p><p class="muted" style="margin:0">A hands-on learning tool for ServiceNow's Common Service Data Model (CSDM).</p></div><div class="actions"><button onclick="closeDialog()">OK</button></div>`;document.getElementById('modal-backdrop').classList.remove('hidden')}function openStatsDialog(){openDialogKey='stats';openDialogPre=null;document.getElementById('modal-title').textContent='Diagram Stats';document.getElementById('modal-body').innerHTML=`<div class="readonly" style="white-space:pre-wrap">${esc(buildStatsText())}</div><div class="actions"><button onclick="closeDialog()">OK</button></div>`;document.getElementById('modal-backdrop').classList.remove('hidden')}let classPhaseFilter='';
function setClassPhaseFilter(p){classPhaseFilter=p||'';openClassesDialog()}
function phaseBadge(phase){const p=phase||'Crawl',col={Crawl:'#0369a1',Walk:'#7c2d12',Run:'#166534',Fly:'#6b21a8'}[p]||'#475569';return `<span style="display:inline-block;padding:2px 7px;border-radius:9px;background:${col};color:#fff;font-size:10px;font-weight:700">${p}</span>`}
function openModelingTrapsDialog(){document.getElementById('modal-title').textContent='Common Modeling Traps';document.getElementById('modal-body').innerHTML=`<p class="muted">Four places nearly everybody puts the data in the wrong class. None of these is a rule you can look up &mdash; they are the judgement calls that decide whether the model is any use, so they are worth reading before you build rather than after.</p>
<div class="qa-section"><h3>1. The Service Desk is a service, not just a process</h3><div class="qa-item"><div>People forget to model the Service Desk as a <strong>Business Service</strong> because they think of it as Incident Management &mdash; a process IT runs. It is both, and they are two different records.</div><div class="qa-why"><strong>Service Desk</strong> = the Business Service employees consume. It is what they ring when something is wrong, and it has its own offerings, support group and SLA.<br><strong>Incident Management</strong> = the Technology Management Service IT runs internally to make that happen.<br>The same split repeats everywhere: <em>Payroll Services</em> is the Business Service employees use; <em>ADP Application Administration</em> is the Technology Management Service IT operates behind it.</div></div></div>
<div class="qa-section"><h3>2. End user services legitimately appear on both sides</h3><div class="qa-item"><div>Desktop is the most confusing area in CSDM because the <em>same</em> capability correctly exists as both a Business Service and a Technology Management Service. This is not duplication and should not be tidied up.</div><div class="qa-why"><strong>What the user sees and consumes:</strong> Business Service <em>Desktop &amp; Laptop Services</em> &rarr; offering <em>Windows Desktop Support</em>; Business Service <em>End User Software</em> &rarr; offering <em>Microsoft 365 / Office Suite</em>.<br><strong>What IT manages behind the scenes:</strong> Technology Management Service <em>End User Technical Services</em> &rarr; offerings <em>Desktop App Patching</em> and <em>Windows Support</em> (OS administration).<br>Two records, two audiences, two support models. Collapsing them loses the ability to report on either.</div></div></div>
<div class="qa-section"><h3>3. EA, Project Management and Business Analysis depend on your org</h3><div class="qa-item"><div>There is no universally correct answer &mdash; placement follows how the function is actually structured and who it serves.</div><div class="qa-why">A common default: <strong>IT Enterprise Architecture</strong> and <strong>IT Project Management</strong> as Technology Management Services (IT-driven standards, roadmaps and delivery), and <strong>Business Process Analysis</strong> as a Business Service, because it serves the business directly. If you have a centralised PMO or EA function serving the whole enterprise rather than just IT, model them as shared Business Services instead. Decide by audience, not by job title.</div></div></div>
<div class="qa-section"><h3>4. Hierarchy lives in the portfolio, never in the services</h3><div class="qa-item"><div>Business Services do not nest inside one another, and neither do Technology Management Services. Both are deliberately flat &mdash; this sandbox will not let you draw those edges.</div><div class="qa-why">Depth belongs to the <strong>Service Portfolio</strong>, which is two levels: a Level 1 category (<em>Workplace</em>, <em>Business &mdash; industry specific</em>, or <em>Shared Services</em>) containing Level 2 functional groupings (<em>End User Services</em>, <em>Finance</em>, <em>Workforce</em>). Services then point at a portfolio. Skipping those levels is what makes portfolio reporting and governance impossible later.</div></div></div>
<div class="actions"><button onclick="closeDialog()">Close</button></div>`;document.getElementById('modal-backdrop').classList.remove('hidden')}
function outOfScopeHtml(){return `<div class="qa-section" style="margin-top:16px"><h3>What this sandbox deliberately leaves out</h3><div class="muted">CSDM 5 spans six domains along a value stream. This tool models three of them plus a corner of a fourth — because its purpose is to let you feel what happens when something breaks, and a record that cannot break cannot cascade. The omissions are a scope decision, not a claim that they do not matter.</div><div class="qa-item"><div><strong>Foundation</strong> — Users, Groups, Locations (Site &rarr; Building &rarr; Floor &rarr; Room), Company, Business Unit, Department, Contracts, Product Models, Business Process, CMDB Group.</div><div class="qa-why">Modeled here as free-text metadata on each node (Owner, Support Group, Approval Group) instead of as referenced records. In a real implementation this domain comes <em>first</em> — approvals and assignment break without it.</div></div><div class="qa-item"><div><strong>Ideation &amp; Strategy</strong> — Product Idea, Planning Item, Strategic Plan, Goals, Value Stream.</div><div class="qa-why">New in CSDM 5 and entirely upstream of anything operational. Nothing in it can fail, so nothing in it can cascade.</div></div><div class="qa-item"><div><strong>Build &amp; Integration</strong> — represented by SDLC Component only.</div><div class="qa-why">DevOps applications, SBOM, and the AI asset family (AI System Digital Asset, AI Model, AI Dataset, AI Prompt) are not modeled.</div></div><div class="qa-item"><div><strong>Service Consumption</strong> — the SPM half is modeled; the CSM half is not.</div><div class="qa-why">Install Base Item, Product Instance, Account, Sold Product and the quote/order chain are absent. So is the AI Service Instance type.</div></div></div>`}
function classTierBadge(type){const t=classTier(type),b=t==='stock'?['Stock CSDM','#15803d']:t==='extended-usable'?['Extended','#1d4ed8']:['Unmapped'+(allowSandboxClasses?'':' · hidden'),'#6b7280'];return `<span style="display:inline-block;padding:2px 7px;border-radius:9px;background:${b[1]};color:#fff;font-size:10px;font-weight:700;white-space:nowrap">${b[0]}</span>`}
function openClassesDialog(){openDialogKey='classes';openDialogPre=null;const types=Object.keys(window.CSDM_SCHEMA.nodeTypes),nStock=types.filter(isStockCsdm).length,nUsable=types.filter(t=>!isStockCsdm(t)&&SERVICENOW_CLASS[t]).length,nHidden=types.filter(t=>!SERVICENOW_CLASS[t]).length;const phaseCounts={};Object.values(window.CSDM_SCHEMA.nodeTypes).forEach(v=>{phaseCounts[v.phase||'Crawl']=(phaseCounts[v.phase||'Crawl']||0)+1});const rows=Object.entries(window.CSDM_SCHEMA.nodeTypes).filter(([name,v])=>!classPhaseFilter||(v.phase||'Crawl')===classPhaseFilter).sort((a,b)=>a[1].level-b[1].level).map(([name,v])=>{const oos=!inPhaseScope(name);return `<tr${oos?' class="class-oos"':''}><td>${v.level}</td><td><strong>${esc(name)}</strong></td><td>${phaseBadge(v.phase)}${oos?' <span class="class-oos-tag">not in build scope</span>':''}</td><td>${classTierBadge(name)}</td><td>${esc(serviceNowClass(name)||'—')}</td><td>${esc(v.domain)}</td><td>${esc(v.description||'')}</td></tr>`}).join('');const phaseBar=`<div style="display:flex;flex-wrap:wrap;align-items:center;gap:6px;margin:10px 0"><span style="font-size:12px;font-weight:700">Maturity phase:</span>${[['','All'],...PHASE_ORDER.map(p=>[p,`${p} (${phaseCounts[p]||0})`])].map(([p,lab])=>`<button class="secondary" style="padding:3px 10px;font-size:12px;${(classPhaseFilter||'')===p?'outline:2px solid #1d4ed8;font-weight:700':'opacity:.75'}" onclick="setClassPhaseFilter('${p}')">${esc(lab)}</button>`).join('')}</div><div class="muted" style="font-size:12px;margin-bottom:8px">${classPhaseFilter?esc(PHASE_UNLOCKS[classPhaseFilter].goal)+' '+PHASE_UNLOCKS[classPhaseFilter].unlocks:`CSDM is a maturity journey — you are not meant to populate all ${types.length} classes. Crawl is what day-one Incident and Change need; Walk makes alerts route themselves; Run turns an outage into a business fact; Fly drives portfolio investment. Filter to see what belongs to each.`}</div>`;
/* Two controls wear these same four words, and only one of them changes what the app does.
   The `Maturity phase` bar above is a view filter on this table (`classPhaseFilter`, not even
   persisted); the build scope under Learn is `activePhases` and gates what the three builders
   may create. Saying so here is the whole point of this block — filtering the table to Walk and
   assuming you had told the tool you are at Walk is the mistake it exists to prevent. */
const buildable=types.filter(inPhaseScope).length,notBuildable=types.length-buildable,filterOos=classPhaseFilter&&!phaseInScope(classPhaseFilter);
const scopeBox=`<div class="explain-box">${phaseScopeIsAll()?`<strong>Build scope: all phases.</strong> Every one of the ${types.length} classes is available in the Interview, Guided Path and Topology builders. Note that the <em>Maturity phase</em> buttons above only change which rows you see in this table &mdash; to change what the builders will actually create, use the <strong>Phase</strong> chips in the status bar.`:`<strong>Build scope: ${esc(activePhases.join(' + '))} &mdash; ${buildable} of ${types.length} classes.</strong> The ${notBuildable} greyed rows below sit outside it: anything you already modeled stays on the canvas and works exactly as before, but the Interview, Guided Path and Topology builders will not create new ones. These are two different controls &mdash; the <em>Maturity phase</em> buttons above only filter this table, while the build scope is set by the <strong>Phase</strong> chips in the status bar.`}</div>${filterOos?`<div class="explain-box explain-bad"><strong>You are filtering this table to ${esc(classPhaseFilter)}, which is not in your build scope (${esc(activePhases.join(' + '))}).</strong> Every row below is therefore a class the builders will currently refuse to create.</div>`:''}`;document.getElementById('modal-title').textContent='Node Classes';document.getElementById('modal-body').innerHTML=`<p class="muted">${types.length} classes — <strong>${nStock}</strong> stock CSDM (the framework itself), <strong>${nUsable}</strong> extended infrastructure (real ServiceNow CMDB classes the services resolve down onto)${nHidden?`, <strong>${nHidden}</strong> unmapped (${allowSandboxClasses?'shown in builders':'hidden from builders'})`:''}. Ordered by layout level (business intent at the top, deep infrastructure at the bottom). The ServiceNow column shows the corresponding CSDM class / table.</p>${nHidden?`<label style="display:flex;align-items:center;gap:8px;margin:6px 0 12px;font-size:13px;font-weight:600"><input type="checkbox" ${allowSandboxClasses?'checked':''} onchange="setAllowSandboxClasses(this.checked)"> Allow the ${nHidden} unmapped classes in the builders</label>`:''}${phaseBar}${scopeBox}<table class="classes-table"><thead><tr><th>Level</th><th>Class (EA)</th><th>Phase</th><th>Status</th><th>ServiceNow</th><th>Domain</th><th>Description</th></tr></thead><tbody>${rows}</tbody></table>${outOfScopeHtml()}<div class="actions"><button onclick="closeDialog()">OK</button></div>`;document.getElementById('modal-backdrop').classList.remove('hidden')}function referenceChip(t){const col=(domainMap[t]||{color:'#64748b'}).color;return `<div style="background:${col};color:#fff;border-radius:8px;padding:7px 6px;font-weight:700;font-size:11px">${esc(t)}</div>`}
function openBusinessReferenceDialog(){const S=window.CSDM_SCHEMA,classes=['Business Capability','Business Application','Application Service','Business Service','Service Offering'],laneName=t=>laneFor(t)===-1?'Design & Plan':laneFor(t)===1?'Sell & Consume':'Convergence';const classRows=classes.map(t=>`<tr><td><strong>${esc(t)}</strong></td><td>${esc(laneName(t))}</td><td>${esc((S.nodeTypes[t]||{}).description||'')}</td></tr>`).join('');const rels=[['Business Application','Provides','Business Capability'],['Business Application','Instantiates','Application Service'],['Business Service','Offers','Service Offering'],['Service Offering','Depends on','Application Service']];const relRows=rels.map(([f,l,t])=>{const r=S.getAllowedRelationship(f,t,l);return `<tr><td><strong>${esc(f)}</strong> &mdash;${esc(l)}&rarr; <strong>${esc(t)}</strong></td><td>${esc(serviceNowRel(l)||'—')}</td><td>${esc(r?r.explanation:'')}</td></tr>`}).join('');document.getElementById('modal-title').textContent='Business Layer Reference';document.getElementById('modal-body').innerHTML=`<p class="muted">The top of a CSDM model is two parallel paths that converge on the Application Service &mdash; the running thing that owns infrastructure. Use this as a template when you set up your own business components.</p><div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;text-align:center;align-items:center;margin:10px 0"><div style="font-size:10px;font-weight:800;color:#64748b;text-transform:uppercase">Design &amp; Plan</div><div style="font-size:10px;font-weight:800;color:#64748b;text-transform:uppercase">Sell &amp; Consume</div>${referenceChip('Business Capability')}${referenceChip('Business Service')}<div class="muted">&#9650; Provides</div><div class="muted">&#9660; Offers</div>${referenceChip('Business Application')}${referenceChip('Service Offering')}</div><div class="muted" style="text-align:center;margin:2px 0">Instantiates &#8600;&nbsp;&nbsp;&#8601; Depends on</div><div style="max-width:220px;margin:0 auto 6px">${referenceChip('Application Service')}</div><div class="muted" style="text-align:center">&#9660; Depends on / Runs on &rarr; Infrastructure</div><h3 style="font-size:14px;margin:10px 0 6px">Classes</h3><table class="classes-table"><thead><tr><th>Class</th><th>Lane</th><th>What it is</th></tr></thead><tbody>${classRows}</tbody></table><h3 style="font-size:14px;margin:12px 0 6px">Relationships</h3><table class="classes-table"><thead><tr><th>Relationship (EA)</th><th>ServiceNow</th><th>Meaning</th></tr></thead><tbody>${relRows}</tbody></table><div class="explain-box" style="margin-top:10px"><strong>Environments:</strong> give each environment (Prod, Stage, Dev) its own Application Service instantiated from the same Business Application, so an outage in one can't make another look degraded. Add a Service Offering only where the environment is actually consumed under a commitment. Tip: right-click an Application Service &rarr; <em>Add Environment</em> to clone its infrastructure tree.</div><div class="actions"><button class="secondary" onclick="loadExample('reference')">Load the Reference Example</button><button onclick="closeDialog()">OK</button></div>`;document.getElementById('modal-backdrop').classList.remove('hidden')}
/* One loader, one table, so the two places that offer "a finished model" cannot drift apart
   again: Start Here loaded the reference example while the tour told you to go and find the
   shared-infra one, purely because this function was hardcoded to a single filename. Both now
   open the shared-infra model — it is the only example with two services over shared
   infrastructure, which is what makes a blast radius worth looking at. Names match the Load
   dialog so the header does not rename a model you can see listed. */
const EXAMPLE_MODELS={reference:{file:'csdmData.reference-example.json',name:'CSDM Reference Example',what:'the reference example'},sharedInfra:{file:'csdmData.shared-infra-example.json',name:'Shared-Infrastructure Example',what:'the shared-infrastructure example'},vmHa:{file:'csdmData.vm-ha-example.json',name:'VM / HA Cluster Example',what:'the VM/HA example'}};
async function loadExample(key){const ex=EXAMPLE_MODELS[key]||EXAMPLE_MODELS.sharedInfra;if(hasUnsavedChanges()&&!confirm(`Loading ${ex.what} will replace your current working model. Continue?`))return;try{const r=await fetch('/api/csdm/load',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({file:ex.file})}),p=await r.json().catch(()=>({}));if(!r.ok)throw new Error(p.error||`Unable to load ${ex.what}.`);try{localStorage.setItem('csdm.currentModelName',ex.name)}catch(_){}window.location.reload()}catch(err){alert(err.message||`Unable to load ${ex.what}.`)}}
function tourLoadDemo(){endTour();loadExample('sharedInfra')}
function updateStatusBar(){const s=document.getElementById('status-text');if(!s)return;if(s.textContent==='Loading...')s.textContent='';populateLargeModelControls();const buttons=document.querySelectorAll('#status-bar button');const undo=[...buttons].find(b=>b.textContent.trim()==='Undo'),redo=[...buttons].find(b=>b.textContent.trim()==='Redo'),save=document.getElementById('status-save-model')||[...buttons].find(b=>b.textContent.trim()==='Save');if(undo)undo.disabled=!undoStack.length;if(redo)redo.disabled=!redoStack.length;if(save)save.disabled=!hasUnsavedChanges();if(window.CSDM_UPDATE_MODEL_NAME_DISPLAY)window.CSDM_UPDATE_MODEL_NAME_DISPLAY()}let lineageHighlight=null;
function buildAdjacency(byId){const adj=new Map();byId.forEach((_,id)=>adj.set(id,[]));currentModelData.edges.forEach(e=>{if(byId.has(e.from)&&byId.has(e.to)){adj.get(e.from).push(e.to);adj.get(e.to).push(e.from)}});return adj}
function traceHighlight(rootId,mode){const byId=new Map(currentModelData.nodes.map(n=>[n.id,n]));if(!byId.has(rootId))return null;const adj=buildAdjacency(byId),lvl=id=>((domainMap[byId.get(id).type]||{level:5}).level),set=new Set([rootId]);if(mode==='vertical'){const walk=dir=>{const st=[rootId];while(st.length){const id=st.pop(),L=lvl(id);adj.get(id).forEach(o=>{const ol=lvl(o);if((dir<0?ol<L:ol>L)&&!set.has(o)){set.add(o);st.push(o)}})}};walk(-1);walk(1)}else{const st=[rootId];while(st.length){const id=st.pop();adj.get(id).forEach(o=>{if(!set.has(o)){set.add(o);st.push(o)}})}}const edges=[];currentModelData.edges.forEach((e,i)=>{if(set.has(e.from)&&set.has(e.to)&&(mode!=='vertical'||lvl(e.from)!==lvl(e.to)))edges.push(i)});return{nodes:[...set],edges}}
function highlightLineage(nodeId,mode){const h=traceHighlight(nodeId,mode||'connected');if(!h)return;lineageHighlight=h;selectedNodeId=nodeId;renderGraph(h)}
function clearLineageHighlight(){const had=lineageHighlight||failureSim;lineageHighlight=null;failureSim=null;stopFailureCostTicker();const b=document.getElementById('failure-banner');if(b)b.remove();hideMenus();closeBarMenus();if(had)renderGraph()}
let failureSim=null;
function simulateFailure(nodeId){const rn=getNode(nodeId);if(rn&&isNonOperational(rn.type))return alert(nonFailableReason(rn.type));const cas=computeCascade(nodeId);if(!cas)return;lineageHighlight=null;const affNodes=[...cas.affected].map(id=>getNode(id)).filter(Boolean),revPerHour=affectedRevenuePerHour(affNodes),full=computeImpact(nodeId),wouldBe=full?affectedRevenuePerHour(full.affected):0;failureSim={failedId:nodeId,affected:cas.affected,protectedNodes:cas.protectedNodes,contained:cas.contained,revenuePerHour:revPerHour,wouldBeRevenue:wouldBe,startTime:Date.now()};selectedNodeId=nodeId;renderGraph();showFailureBanner(cas);startFailureCostTicker();if(networkInstance)try{networkInstance.focus(nodeId,{scale:networkInstance.getScale(),animation:{duration:250}})}catch(_){}}
function showFailureBanner(cas){const meta=n=>n.metadata||{},root=cas.root,affectedNodes=[...cas.affected].map(id=>getNode(id)).filter(Boolean),slas=affectedNodes.filter(n=>n.type==='Service Offering'&&meta(n).availabilityTarget),crit=affectedNodes.filter(n=>n.type==='Business Capability'&&/Critical/.test(meta(n).criticality||''));let b=document.getElementById('failure-banner');if(!b){b=document.createElement('div');b.id='failure-banner';document.body.appendChild(b)}let parts;if(cas.contained){parts=[`<strong>FAILURE ABSORBED</strong> &mdash; ${esc(root.label)} is redundant (${esc(meta(root).redundancy)})`,`a single failure is tolerated &mdash; no business impact`]}else{parts=[`<strong>FAILURE SIMULATION</strong> &mdash; ${esc(root.label)} is down`,`<strong>${cas.affected.size}</strong> component(s) impacted`];if(slas.length)parts.push(`SLAs at risk: ${slas.map(o=>esc(o.label)+' ('+esc(meta(o).availabilityTarget)+')').join(', ')}`);if(crit.length)parts.push(`critical: ${crit.map(c=>esc(c.label)).join(', ')}`);if(cas.protectedNodes.size)parts.push(`${cas.protectedNodes.size} protected by redundancy`)}const whatif=supportsRedundancy(root.type)?`<button class="fb-whatif" onclick="whatIfToggleRedundancy('${esc(root.id)}')">${isResilient(root)?'What-if: make single-instance':'What-if: add redundancy'}</button>`:'';let costHtml='';if(cas.contained){if(failureSim&&failureSim.wouldBeRevenue>0)costHtml=`<div class="fb-cost fb-cost-saved">Redundancy is saving <strong>${formatMoney(failureSim.wouldBeRevenue)}/hr</strong></div>`}else if(failureSim&&failureSim.revenuePerHour>0)costHtml=`<div class="fb-cost">Revenue at risk <strong>${formatMoney(failureSim.revenuePerHour)}/hr</strong> &middot; lost so far <strong id="fb-lost">$0</strong></div>`;const rediscover=canReDiscover(root.id)?`<button class="fb-rediscover" onclick="reRunDiscovery('${esc(root.id)}')">Re-run Discovery</button>`:'';b.className=cas.contained?'fb-contained':'';b.innerHTML=`<div class="fb-text">${parts.join(' &nbsp;|&nbsp; ')}</div>${costHtml}${rediscover}${whatif}<button onclick="clearLineageHighlight()">Clear</button>`}
