function openDashboardDialog(){document.getElementById('modal-title').textContent='Portfolio Health Dashboard';document.getElementById('modal-body').innerHTML=dashboardHtml();document.getElementById('modal-backdrop').classList.remove('hidden')}
/* ---- Incident Replay ("2am page"): walk the CSDM dependency chain from a business symptom down to root cause, one hop at a time. ---- */
let incidentReplay=null;
const INCIDENT_BUSINESS_RANK={'Business Capability':6,'Business Service':5,'Service Offering':5,'Service Portfolio':4,'Application Service':3,'Technical Service':3,'Technical Service Offering':3};
function incidentBizRank(n){return (n&&INCIDENT_BUSINESS_RANK[n.type])||0}
function pad2(n){return (n<10?'0':'')+n}
function incidentClock(mins){const t=2*60+(mins||0),h=Math.floor(t/60)%24,m=t%60;return pad2(h)+':'+pad2(m)}
function incidentHopMinutes(node,isRoot){const cat=impactCategory(node);let m=(cat==='data'||cat==='storage'||cat==='security')?4:3;if(isRoot)m+=1;return m}
function findEdgeBetween(a,b){let idx=-1,edge=null;currentModelData.edges.forEach((e,i)=>{if(idx>=0)return;if((e.from===a&&e.to===b)||(e.from===b&&e.to===a)){idx=i;edge=e}});return{idx,edge}}
function incidentSymptomText(n){const m=n.metadata||{},t=n.type;if(t==='Business Capability')return `The business can no longer do this${m.criticality?` (${esc(m.criticality)})`:''} &mdash; the desk is on the phone. Nobody yet knows why.`;if(t==='Business Service')return `Consumers report the service is unavailable. Nobody yet knows which piece broke.`;if(t==='Service Offering')return `Availability is breaching${m.availabilityTarget?` its ${esc(m.availabilityTarget)} commitment`:` its commitment`}. Nobody yet knows the cause.`;if(t==='Application Service')return `Synthetic checks are red &mdash; requests timing out${m.environment?` in ${esc(m.environment)}`:''}. Nobody yet knows the cause.`;return `Monitoring is red. Nobody yet knows the cause.`}
function pickIncidentRoot(){const d=buildDashboard();if(d.spofs&&d.spofs.length)return d.spofs[0].node.id;const byId=new Map(currentModelData.nodes.map(n=>[n.id,n]));let best=null,bestScore=-1;currentModelData.nodes.forEach(n=>{if(isNonOperational(n.type))return;const cas=computeCascade(n.id);if(!cas||cas.contained)return;const aff=[...cas.affected].map(id=>byId.get(id)).filter(Boolean);if(!aff.some(x=>incidentBizRank(x)>=3))return;const score=aff.reduce((s,x)=>s+incidentBizRank(x),0)+cas.affected.size;if(score>bestScore){bestScore=score;best=n.id}});return best}
function buildIncidentPath(rootId){const byId=new Map(currentModelData.nodes.map(n=>[n.id,n])),root=byId.get(rootId);if(!root)return{root:null,cas:null,affected:[],symptom:null,chain:[],byId};const cas=computeCascade(rootId),g=buildImpactGraph(),parent=new Map(),dist=new Map();dist.set(rootId,0);const q=[rootId];while(q.length){const id=q.shift();(g.fwd.get(id)||[]).forEach(o=>{if(!dist.has(o)){dist.set(o,dist.get(id)+1);parent.set(o,id);q.push(o)}})}const affected=(cas?[...cas.affected]:[]).map(id=>byId.get(id)).filter(Boolean);let symptom=null,best=[-1,-1,-1];affected.forEach(n=>{if(!dist.has(n.id))return;const score=[incidentBizRank(n),dist.get(n.id),revenuePerHour(n)];if(score[0]>best[0]||(score[0]===best[0]&&score[1]>best[1])||(score[0]===best[0]&&score[1]===best[1]&&score[2]>best[2])){best=score;symptom=n}});const chain=[];if(symptom){let cur=symptom.id;const guard=new Set();while(cur!=null&&!guard.has(cur)){guard.add(cur);chain.push(cur);cur=parent.has(cur)?parent.get(cur):null}}return{root,cas,affected,symptom,chain,byId}}
function startIncidentReplay(nodeId){hideMenus();closeBarMenus();let rootId=(nodeId&&getNode(nodeId))?nodeId:pickIncidentRoot();if(!rootId)return alert(`No incident to replay yet &mdash; this model has no operational component whose failure reaches a business service. Add infrastructure under an Application Service and link it up to a Service Offering or Business Capability first.`.replace(/&mdash;/g,'—'));const root=getNode(rootId);if(isNonOperational(root.type))return alert(nonFailableReason(root.type));const p=buildIncidentPath(rootId),contained=!!(p.cas&&p.cas.contained),chain=p.chain||[],steps=[];if(!contained&&chain.length){let t=0;for(let k=0;k<chain.length;k++){const node=p.byId.get(chain[k]),isRoot=k===chain.length-1,isPage=k===0;if(k>0)t+=incidentHopMinutes(node,isRoot);const edgeIdx=[];for(let j=1;j<=k;j++){const fe=findEdgeBetween(chain[j-1],chain[j]);if(fe.idx>=0)edgeIdx.push(fe.idx)}steps.push({time:t,nodeId:chain[k],nodeIds:chain.slice(0,k+1),edgeIdx,isRoot,isPage})}}incidentReplay={rootId,root,contained,chain,steps,step:0,timer:null,affectedCount:p.cas?p.cas.affected.size:0,rev:affectedRevenuePerHour(p.affected||[])};document.getElementById('modal-title').textContent='Incident Replay — 2:00 AM Page';document.getElementById('modal-body').innerHTML=incidentReplayHtml();document.getElementById('modal-backdrop').classList.remove('hidden');makeDialogDraggable();renderIncidentCanvas()}
function incidentStepCard(k){const ir=incidentReplay,step=ir.steps[k],node=getNode(step.nodeId);let cls='ir-step';if(step.isRoot)cls+=' ir-step-root';else if(step.isPage)cls+=' ir-step-page';let body;if(step.isPage)body=`<strong>${esc(node.label)}</strong> is the alerting service. Start the trace here.`;else{const prev=getNode(ir.chain[k-1]),fe=findEdgeBetween(ir.chain[k-1],ir.chain[k]);let phrase;if(fe.edge){const lbl=esc((fe.edge.label||'depends on').toLowerCase());phrase=fe.edge.from===ir.chain[k-1]?`${esc(prev.label)} ${lbl} ${esc(node.label)}`:`${esc(node.label)} ${lbl} ${esc(prev.label)}`}else phrase=`${esc(prev.label)} depends on ${esc(node.label)}`;if(step.isRoot)body=`Service map: <em>${phrase}</em>. <strong>${esc(node.label)}</strong> [${esc(node.type)}] is <span class="ir-down">DOWN</span> &mdash; <strong>root cause found.</strong>${node.metadata&&node.metadata.environment?` Environment: ${esc(node.metadata.environment)}.`:''}`;else body=`Service map: <em>${phrase}</em>. <strong>${esc(node.label)}</strong> [${esc(node.type)}] is degraded &mdash; follow its dependency down a layer.`}return `<div class="${cls}"><div class="ir-step-time">${incidentClock(step.time)}</div><div class="ir-step-body">${body}</div></div>`}
function incidentPayoffHtml(){const ir=incidentReplay,steps=ir.steps,hops=ir.chain.length-1,mins=steps.length?steps[steps.length-1].time:0,revLine=ir.rev>0?`<br>Revenue at risk while down: <strong>${formatMoney(ir.rev)}/hr</strong> (${formatMoney(ir.rev*mins/60)} bled during this ${mins}-minute triage).`:'';return `<div class="qa-section qa-good ir-payoff"><h3>Why the model earned its keep</h3><div>Symptom to root cause in <strong>${hops} hop${hops===1?'':'s'}</strong>, about <strong>${mins} minutes</strong> &mdash; because the CSDM graph already had the dependency path written down.<br><span class="impact-flag">Without the model:</span> a 2am bridge call, ${ir.affectedCount} component(s) in scope, each team ruling out its own layer by hand &mdash; mean-time-to-identify measured in hours.${revLine}</div><div class="actions" style="justify-content:flex-start"><button class="secondary" onclick="closeDialog();simulateFailure('${esc(ir.rootId)}')">See full blast radius</button><button class="secondary" onclick="closeDialog();openImpactDialog('${esc(ir.rootId)}')">Impact analysis</button><button onclick="closeDialog()">Close</button></div></div>`}
function incidentReplayHtml(){const ir=incidentReplay;if(!ir)return '<p>No incident.</p>';const root=ir.root,m=root.metadata||{};if(ir.contained)return `<div class="ir-pager ir-quiet"><div class="ir-pager-head"><span class="ir-sev ir-sev-ok">NO PAGE</span><span class="ir-time">${incidentClock(0)}</span><span class="ir-page-label">2:00 AM</span></div><div class="ir-pager-body"><strong>${esc(root.label)}</strong> [${esc(root.type)}] failed overnight &mdash; and you slept through it.</div></div><div class="qa-section qa-good"><h3>Redundancy absorbed it</h3><div>${esc(root.label)} is <strong>${esc(m.redundancy||'redundant')}</strong>, so the failure was tolerated: nothing downstream noticed, no customer impact, no page.<br>This is the other half of why the model exists &mdash; it doesn&rsquo;t just tell you what breaks, it shows you what <em>won&rsquo;t</em>, so you know where redundancy is actually buying you a quiet night.</div><div class="actions" style="justify-content:flex-start"><button class="secondary" onclick="closeDialog();whatIfToggleRedundancy('${esc(ir.rootId)}')">What-if: remove its redundancy</button><button onclick="closeDialog()">Close</button></div></div>`;if(!ir.chain.length)return `<div class="ir-pager ir-quiet"><div class="ir-pager-head"><span class="ir-sev ir-sev-ok">LOW</span><span class="ir-time">${incidentClock(0)}</span><span class="ir-page-label">2:00 AM</span></div><div class="ir-pager-body"><strong>${esc(root.label)}</strong> [${esc(root.type)}] failed &mdash; but nothing depends on it.</div></div><div class="qa-section qa-good"><h3>Contained failure</h3><div>${esc(root.label)} is a leaf in the dependency graph: no service, offering, or capability sits above it, so its failure reaches no customer. The model tells you this is a low-severity page that can wait until morning &mdash; a judgment you cannot make without the graph.</div><div class="actions" style="justify-content:flex-start"><button onclick="closeDialog()">Close</button></div></div>`;const steps=ir.steps,cur=ir.step,symptom=getNode(ir.chain[0]),atEnd=cur>=steps.length-1;let html=`<div class="ir-pager"><div class="ir-pager-head"><span class="ir-sev">SEV1</span><span class="ir-time">${incidentClock(0)}</span><span class="ir-page-label">PAGE</span></div><div class="ir-pager-body"><strong>${esc(symptom.label)}</strong> [${esc(symptom.type)}]<br>${incidentSymptomText(symptom)}</div></div>`;html+=`<p class="muted">You are on call. All you were handed is the symptom above. Walk the CSDM dependency chain from symptom to root cause &mdash; one hop at a time.</p>`;html+=`<div class="ir-timeline">`;for(let k=0;k<=cur;k++)html+=incidentStepCard(k);html+=`</div>`;html+=`<div class="ir-controls"><button class="secondary" onclick="incidentReplayGo(0)" ${cur===0?'disabled':''}>Restart</button><button class="secondary" onclick="incidentReplayGo(${cur-1})" ${cur===0?'disabled':''}>Back</button>`;if(!atEnd)html+=`<button onclick="incidentReplayPlay()">${ir.timer?'Pause':'Play'}</button>`;html+=`<button onclick="incidentReplayGo(${cur+1})" ${atEnd?'disabled':''}>${cur===0?'Start tracing ▸':'Next hop ▸'}</button></div>`;if(atEnd)html+=incidentPayoffHtml();return html}
function renderIncidentCanvas(){if(!incidentReplay)return;const st=incidentReplay.steps[incidentReplay.step],nodes=st?st.nodeIds:[incidentReplay.rootId],edges=st?st.edgeIdx:[];lineageHighlight={nodes:nodes.slice(),edges:edges.slice()};selectedNodeId=st?st.nodeId:incidentReplay.rootId;pendingFocusNodeId=selectedNodeId;renderGraph(lineageHighlight)}
function incidentReplayStop(){if(incidentReplay&&incidentReplay.timer){clearInterval(incidentReplay.timer);incidentReplay.timer=null}}
function incidentReplayGo(i){if(!incidentReplay)return;incidentReplayStop();const steps=incidentReplay.steps;incidentReplay.step=Math.max(0,Math.min(i,steps.length-1));document.getElementById('modal-body').innerHTML=incidentReplayHtml();renderIncidentCanvas()}
function incidentReplayPlay(){if(!incidentReplay)return;if(incidentReplay.timer){incidentReplayStop();document.getElementById('modal-body').innerHTML=incidentReplayHtml();return}incidentReplay.timer=setInterval(()=>{const backdrop=document.getElementById('modal-backdrop');if(!incidentReplay||!backdrop||backdrop.classList.contains('hidden'))return incidentReplayStop();if(incidentReplay.step>=incidentReplay.steps.length-1){incidentReplayStop();document.getElementById('modal-body').innerHTML=incidentReplayHtml();renderIncidentCanvas();return}incidentReplay.step++;document.getElementById('modal-body').innerHTML=incidentReplayHtml();renderIncidentCanvas()},1500);document.getElementById('modal-body').innerHTML=incidentReplayHtml()}
function highlightFinding(nodes,edges){closeDialog();renderGraph({nodes:nodes||[],edges:edges||[]});if(networkInstance&&nodes?.length)networkInstance.focus(nodes[0],{scale:1.2,animation:true})}function openRelationshipExplanation(i){}function esc(v){return String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#039;')}
const TOUR_STEPS=[
{title:'Welcome to the CSDM Sandbox',target:null,body:'This is a hands-on tool for learning ServiceNow’s Common Service Data Model — how a business connects what it does (capabilities and services) to the infrastructure that runs it. This 60-second tour points out the main features. You can replay it any time from the Learn menu.'},
{title:'The model reads top to bottom',target:'#network-canvas',body:'A CSDM model flows from business intent down to infrastructure. Two lanes at the top — <strong>Design &amp; Plan</strong> (capability, application) on the left and <strong>Sell &amp; Consume</strong> (business service, offering) on the right — converge on the running <strong>Application Service</strong>, which sits on top of clusters, databases, and the rest of the stack.'},
{title:'Build — every way into the model',target:'#build-menu-btn',body:'<strong>Start Here</strong> reopens the three-card front door at any time. <strong>Interview</strong> takes plain prose. The <strong>Guided CSDM Path</strong> walks the layers in order, the <strong>Topology Builder</strong> stacks infrastructure, and the <strong>Relationship Builder</strong> joins two things you already have. None of them will let you create a relationship CSDM does not allow. The four builders are also on the <strong>canvas right-click</strong>, which is the faster habit once you know what you want.'},
{title:'Phase chips — how much CSDM to take on at once',target:'#phase-scope-bar',body:'CSDM is meant to be adopted in stages, and these chips are those stages. <strong>Crawl</strong> is the 13-class foundation every model needs, <strong>Walk</strong> adds 30 more, and <strong>Run</strong> and <strong>Fly</strong> add the last 9 — 52 classes in all, far too many to meet on day one. Your scope decides what the <strong>builders may create</strong>: Interview Mode, the Guided Path and the Topology Builder only offer classes inside it, and anything they leave out says which phase would unlock it. They deliberately do <em>not</em> hide what is already on the canvas — impact analysis has to see the whole model, or it would under-report what actually breaks.'},
{title:'View menu — change what you see',target:'#view-menu-btn',body:'Switch <strong>View Modes</strong> (business-only, infrastructure-only, per-layer colors), filter by relationship, cluster by domain, and clear highlights — all grouped here to keep the bar clean.'},
{title:'Config — how the builders behave',target:'#config-menu-btn',body:'Two settings live here. <strong>Learning Mode</strong> flips the builders from hand-holding to being quizzed: you pick the relationship, and it tells you whether CSDM agrees. The <strong>interview parser</strong> is where an Anthropic API key goes if you want Interview Mode to read looser phrasing — it works without one, using a built-in vocabulary. When either is switched on the button says so, so you are never in a mode you forgot about.'},
{title:'Analyze — ask the model what breaks',target:'#analyze-menu-btn',body:'This is why you built it. <strong>Explain</strong> reads your model back in plain English, the <strong>Coach</strong> checks it is complete the CSDM way and says why each gap matters, the <strong>Dashboard</strong> rolls up cost, single points of failure and resilience, and <strong>2am Incident Replay</strong> drops you into the page nobody wants. <strong>Stats</strong> counts what you have.'},
{title:'Learn — look things up',target:'#learn-menu-btn',body:'This tour lives here, alongside the lookups: <strong>Reference</strong> (what each business-layer class is for), <strong>Modeling Traps</strong> (four places nearly everyone puts data in the wrong class), and <strong>Classes</strong> (all 52, with their real ServiceNow names). Start Here moved to <strong>Build ▾</strong> — it is a way into a first model, not a thing to read.'},
{title:'Node actions live on right-click',target:'#network-canvas',body:'Right-click any node for <strong>Focus on This Node</strong> (centre the canvas on it and its neighbours — right-click it again to come back), <strong>Open Node Details</strong>, <strong>Impact Analysis</strong>, <strong>Simulate Failure</strong>, <strong>Highlight Lineage</strong>, <strong>Add Environment</strong> (clone a service into Prod/Stage/Dev), and <strong>Delete</strong>.'},
{title:'Impact Analysis — the payoff',target:'#network-canvas',body:'This is why you build the model. Right-click a node → <strong>Impact Analysis</strong> to answer, in business language: what breaks if this fails (blast radius &amp; SLAs), what to test/notify before a change, what it costs, and what data it exposes. <strong>Simulate Failure</strong> lights the cascade up in red across the canvas.'},
{title:'See it shine — load the demo',target:'#file-menu-btn',body:'The <strong>★ Shared-Infrastructure Example</strong> has two trading services sharing a cluster but with separate databases — so you can watch Impact Analysis correctly show a shared-cluster failure hitting <em>both</em> services while a single database failure hits only one.<div class="tour-load"><button class="tour-primary" onclick="tourLoadDemo()">Load it now</button></div>It is also under <strong>File ▾ &rarr; Open</strong> any time, along with the other examples. Enjoy exploring!'}
];
let tourIndex=0;
function startTour(){tourIndex=0;renderTourStep()}
function endTour(){try{localStorage.setItem('csdm.tourSeen','1')}catch(_){}['tour-backdrop','tour-card'].forEach(id=>{const el=document.getElementById(id);if(el)el.remove()})}
function tourNext(){if(tourIndex>=TOUR_STEPS.length-1)return endTour();tourIndex++;renderTourStep()}
function tourPrev(){if(tourIndex>0){tourIndex--;renderTourStep()}}
function renderTourStep(){const step=TOUR_STEPS[tourIndex];let bd=document.getElementById('tour-backdrop');if(!bd){bd=document.createElement('div');bd.id='tour-backdrop';document.body.appendChild(bd)}let card=document.getElementById('tour-card');if(!card){card=document.createElement('div');card.id='tour-card';document.body.appendChild(card)}const target=step.target?document.querySelector(step.target):null;if(target){const r=target.getBoundingClientRect();bd.classList.remove('tour-full');bd.style.top=(r.top-6)+'px';bd.style.left=(r.left-6)+'px';bd.style.width=(r.width+12)+'px';bd.style.height=(r.height+12)+'px'}else{bd.classList.add('tour-full');bd.style.top=bd.style.left=bd.style.width=bd.style.height=''}card.innerHTML=`<div class="tour-count">Step ${tourIndex+1} of ${TOUR_STEPS.length}</div><h3>${esc(step.title)}</h3><div class="tour-body">${step.body}</div><div class="tour-actions"><button class="tour-skip" onclick="endTour()">Skip</button><div class="tour-nav"><button ${tourIndex===0?'disabled':''} onclick="tourPrev()">Back</button><button class="tour-primary" onclick="tourNext()">${tourIndex===TOUR_STEPS.length-1?'Done':'Next'}</button></div></div>`;const cr=card.getBoundingClientRect();if(target){const r=target.getBoundingClientRect(),spaceBelow=window.innerHeight-r.bottom;let top=spaceBelow>cr.height+24?r.bottom+14:Math.max(12,r.top-cr.height-14),left=Math.min(Math.max(12,r.left),window.innerWidth-cr.width-12);card.style.top=top+'px';card.style.left=left+'px';card.style.transform=''}else{card.style.top='50%';card.style.left='50%';card.style.transform='translate(-50%,-50%)'}}
function maybeAutoTour(){let seen=false;try{seen=!!localStorage.getItem('csdm.tourSeen')}catch(_){}if(!seen)setTimeout(startTour,900)}
/* Start Here shows itself whenever the model is empty — the one state where the canvas gives no
   clue what to do — and can also be opened deliberately from Learn, because a first-time user
   lands on a populated demo model and would otherwise never reach it.
   Keyed on currentModelData.nodes.length, NOT the filtered graph: a view filter that hides
   everything also renders zero nodes, and answering that with "start here" would be a lie. */
let startHereManual=false,startHereDismissed=false;
function syncEmptyState(){const el=document.getElementById('empty-state');if(!el)return;const empty=!currentModelData.nodes.length;if(!empty)startHereDismissed=false;el.classList.toggle('hidden',!(startHereManual||(empty&&!startHereDismissed)))}
function showStartHere(){startHereManual=true;startHereDismissed=false;hideMenus();closeBarMenus();syncEmptyState()}
function closeStartHere(){startHereManual=false;startHereDismissed=true;syncEmptyState()}
function startHereGo(what){closeStartHere();if(what==='interview')return window.CSDM_START_INTERVIEW?window.CSDM_START_INTERVIEW():alert('Interview Mode is not available.');if(what==='example')return loadExample('sharedInfra');if(what==='guided')return openDialog('dialog-guided');if(what==='tour')return startTour()}
loadSandbox();maybeAutoTour();
